import { render, screen } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import UserStats from './UserStats';

describe('UserStats', () => {
  it('displays correct statistics for a mix of active and inactive users', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: false },
      { id: 3, name: 'User 3', isActive: true },
      { id: 4, name: 'User 4', isActive: true },
    ];
    // Total 4, Active 3, Inactive 1
    // Percentage: 3/4 * 100 = 75%

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 3')).toBeDefined();
    expect(screen.getByText('Inactive Users: 1')).toBeDefined();
    expect(screen.getByText('Active Percentage: 75.0%')).toBeDefined();
  });

  it('displays correct statistics when all users are inactive', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: false },
      { id: 2, name: 'User 2', isActive: false },
    ];
    // Active 0, Inactive 2, Percentage 0%

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 0')).toBeDefined();
    expect(screen.getByText('Inactive Users: 2')).toBeDefined();
    expect(screen.getByText('Active Percentage: 0.0%')).toBeDefined();
  });

  it('handles empty user list', () => {
    const users: any[] = [];

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 0')).toBeDefined();
    expect(screen.getByText('Inactive Users: 0')).toBeDefined();
    expect(screen.getByText('Active Percentage: 0.0%')).toBeDefined();
  });
});

